using System.Security.Claims; using AccessHub.Api.Data; using AccessHub.Api.DTOs; using AccessHub.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AccessHub.Api.Controllers;
[ApiController][Authorize][Route("api/profile")]
public class ProfileController(AccessHubDbContext db):ControllerBase
{
 private int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); private readonly PasswordHasher<User> hasher=new();
 [HttpGet] public async Task<IActionResult> Get(){var u=await db.Users.FindAsync(UserId);if(u==null)return NotFound();return Ok(new{userId=u.Id,firstName=u.FirstName,surname=u.Surname,email=u.Email,phoneNumber=u.PhoneNumber,preferredLanguage=u.PreferredLanguage,notificationEnabled=u.NotificationEnabled,points=u.Points});}
 [HttpPut] public async Task<IActionResult> Update(UpdateProfileRequest r){var u=await db.Users.FindAsync(UserId);if(u==null)return NotFound();u.FirstName=r.FirstName.Trim();u.Surname=r.Surname.Trim();u.PhoneNumber=r.PhoneNumber.Trim();u.PreferredLanguage=r.PreferredLanguage;u.NotificationEnabled=r.NotificationEnabled;await db.SaveChangesAsync();return Ok(new{message="Profile updated successfully."});}
 [HttpPut("password")] public async Task<IActionResult> Password(ChangePasswordRequest r){var u=await db.Users.FindAsync(UserId);if(u==null)return NotFound();if(r.NewPassword.Length<8)return BadRequest(new{message="New password must be at least 8 characters."});if(hasher.VerifyHashedPassword(u,u.PasswordHash,r.CurrentPassword)==PasswordVerificationResult.Failed)return BadRequest(new{message="Current password is incorrect."});u.PasswordHash=hasher.HashPassword(u,r.NewPassword);await db.SaveChangesAsync();return Ok(new{message="Password changed successfully."});}
 [HttpDelete] public async Task<IActionResult> Delete(){var u=await db.Users.FindAsync(UserId);if(u==null)return NotFound();var requests=await db.Requests.Where(x=>x.UserId==UserId).ToListAsync();var notifications=await db.Notifications.Where(x=>x.UserId==UserId).ToListAsync();var achievements=await db.UserAchievements.Where(x=>x.UserId==UserId).ToListAsync();db.Requests.RemoveRange(requests);db.Notifications.RemoveRange(notifications);db.UserAchievements.RemoveRange(achievements);db.Users.Remove(u);await db.SaveChangesAsync();return Ok(new{message="Account deleted successfully."});}
 [HttpPost("fcm-token")] public async Task<IActionResult> Fcm(RegisterFcmToken r){var u=await db.Users.FindAsync(UserId);if(u==null)return NotFound();if(string.IsNullOrWhiteSpace(r.FcmToken))return BadRequest(new{message="FCM token is required."});u.FcmToken=r.FcmToken.Trim();await db.SaveChangesAsync();return Ok(new{message="FCM token registered."});}
}
